package com.turboio.addon;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.*;
import javax.net.ssl.HttpsURLConnection;import java.io.*;import java.net.*;import java.security.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;

/** User-triggered checks and downloads; this page never polls or flashes in the background. */
final class AgentUpdateUI {
 private static final ExecutorService IO=Executors.newSingleThreadExecutor();
 static void show(Activity a){
  AgentUI.Screen screen=new AgentUI.Screen(a,"更新中心");Handler main=new Handler(Looper.getMainLooper());AtomicBoolean closed=new AtomicBoolean();boolean[] busy={false};AppRelease[] release={null};File[] archive={null};
  screen.dialog.setOnDismissListener(d->closed.set(true));AgentUI.summary(a,screen.body,"refresh","iO Agent 更新","检查已适配、已验证的安装包");
  LinearLayout app=AgentUI.section(a,screen.body,"手机应用");AgentUI.row(a,app,"当前版本",null,ProductInfo.VERSION,null);AgentUI.divider(a,app);TextView status=AgentUI.text(a,"点击检查更新；不会在后台自动下载。",14,AgentUI.MUTED);app.addView(status);AgentUI.gap(a,app,12);
  TextView[] check={null},download={null},install={null};
  check[0]=AgentUI.button(a,app,"检查更新",false,()->{if(busy[0])return;busy[0]=true;check[0].setEnabled(false);download[0].setVisibility(android.view.View.GONE);install[0].setVisibility(android.view.View.GONE);release[0]=null;archive[0]=null;status.setText("正在检查已发布版本…");
   IO.execute(()->{AppRelease found=null;String message="";HttpsURLConnection request=null;try{
    request=(HttpsURLConnection)new URL("https://cznbnb.cn/io-updates/latest.json").openConnection();request.setConnectTimeout(5000);request.setReadTimeout(10000);request.setInstanceFollowRedirects(false);request.setUseCaches(false);
    int response=request.getResponseCode();if(response==404)message="暂时没有发布新的适配版本。";else{if(response!=200)throw new IOException("UPDATE_SERVER_UNAVAILABLE");ByteArrayOutputStream body=new ByteArrayOutputStream();try(InputStream in=request.getInputStream()){byte[] block=new byte[4096];for(int n;(n=in.read(block))!=-1;){if(body.size()+n>32768)throw new IOException("UPDATE_RELEASE_INVALID");body.write(block,0,n);}}
     found=new AppRelease(body.toByteArray(),a.getPackageName());PackageInfo current=a.getPackageManager().getPackageInfo(a.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);MaterialWire.require(found.signer.equals(signer(current)),"UPDATE_SIGNER_MISMATCH");
     message=found.code>current.getLongVersionCode()?"新版本 "+found.version+" · "+(found.bytes/1048576)+" MiB\n"+android.text.TextUtils.join("\n",found.notes):"当前已是最新适配版本。\n"+found.version;
     if(found.code<=current.getLongVersionCode())found=null;
    }
   }catch(Exception error){message=label(error);}finally{if(request!=null)request.disconnect();}AppRelease ready=found;String text=message;main.post(()->{if(closed.get())return;busy[0]=false;check[0].setEnabled(true);release[0]=ready;status.setText(text);download[0].setVisibility(ready==null?android.view.View.GONE:android.view.View.VISIBLE);});});
  });
  download[0]=AgentUI.button(a,app,"下载安装包",true,()->{if(busy[0]||release[0]==null)return;AppRelease target=release[0];busy[0]=true;download[0].setEnabled(false);check[0].setEnabled(false);status.setText("正在下载 "+target.version+"，关闭本页可取消。");
   IO.execute(()->{File part=new File(a.getCacheDir(),"io-update.apk.partial"),apk=new File(a.getCacheDir(),"io-update.apk");File ready=null;String message="";HttpsURLConnection request=null;
    try{request=(HttpsURLConnection)new URL(target.url).openConnection();request.setConnectTimeout(10000);request.setReadTimeout(15000);request.setInstanceFollowRedirects(false);request.setUseCaches(false);if(request.getResponseCode()!=200||request.getContentLengthLong()!=target.bytes)throw new IOException("UPDATE_DOWNLOAD_INCOMPLETE");MessageDigest hash=MessageDigest.getInstance("SHA-256");long count=0,last=0;
     try(InputStream in=request.getInputStream();FileOutputStream out=new FileOutputStream(part)){byte[] block=new byte[65536];for(int n;(n=in.read(block))!=-1;){if(closed.get())throw new InterruptedIOException("UPDATE_CANCELLED");count+=n;if(count>target.bytes)throw new IOException("UPDATE_DOWNLOAD_INCOMPLETE");hash.update(block,0,n);out.write(block,0,n);long now=System.currentTimeMillis();if(now-last>=1000){last=now;long progress=count;main.post(()->{if(!closed.get())status.setText("正在下载 "+progress*100/target.bytes+"% · "+(progress/1048576)+" / "+(target.bytes/1048576)+" MiB");});}}out.getFD().sync();}
     MaterialWire.require(count==target.bytes&&target.sha256.equals(hex(hash.digest())),"UPDATE_HASH_MISMATCH");PackageInfo info=a.getPackageManager().getPackageArchiveInfo(part.getAbsolutePath(),PackageManager.GET_SIGNING_CERTIFICATES);MaterialWire.require(info!=null&&a.getPackageName().equals(info.packageName)&&info.getLongVersionCode()==target.code&&target.signer.equals(signer(info)),"UPDATE_ARCHIVE_MISMATCH");
     if(apk.exists()&&!apk.delete())throw new IOException("UPDATE_STORAGE_FAILED");if(!part.renameTo(apk))throw new IOException("UPDATE_STORAGE_FAILED");ready=apk;message="下载及签名核对完成，可以交给系统安装。账号和资料会保留。";
    }catch(Exception error){message=label(error);}finally{if(request!=null)request.disconnect();if(part.exists())part.delete();}File verified=ready;String text=message;main.post(()->{if(closed.get())return;busy[0]=false;check[0].setEnabled(true);download[0].setEnabled(true);archive[0]=verified;status.setText(text);install[0].setVisibility(verified==null?android.view.View.GONE:android.view.View.VISIBLE);});});
  });download[0].setVisibility(android.view.View.GONE);
  install[0]=AgentUI.button(a,app,"交给系统安装",true,()->{if(archive[0]==null)return;if(!a.getPackageManager().canRequestPackageInstalls()){AgentUI.notice(a,"请在系统页面允许 iO Agent 安装更新，再返回点击安装。");a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));return;}
   try{Class<?> provider=Class.forName("com.blankj.utilcode.util.UtilsFileProvider").getSuperclass();Method factory=null;for(Method method:provider.getDeclaredMethods())if(Modifier.isStatic(method.getModifiers())&&method.getReturnType()==Uri.class&&Arrays.equals(method.getParameterTypes(),new Class<?>[]{Context.class,String.class,File.class})){factory=method;break;}if(factory==null)throw new IOException("UPDATE_INSTALLER_UNAVAILABLE");Uri uri=(Uri)factory.invoke(null,a,a.getPackageName()+".utilcode.fileprovider",archive[0]);a.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception failure){AgentUI.notice(a,"系统安装入口未能打开，请重试。安装包仍保留。");}
  });install[0].setVisibility(android.view.View.GONE);
  LinearLayout glasses=AgentUI.section(a,screen.body,"眼镜固件");AgentUI.iconRow(a,glasses,"glasses","核对固件与适配候选","已适配固定60秒候选：Strix OS 1.0.5.5",null,()->Fixed60UI.show(a,screen.dialog::dismiss));AgentUI.gap(a,screen.body,16);screen.body.addView(AgentUI.text(a,"新原厂版本需完成适配后才会发布。眼镜升级需你主动确认版本、电量及本次安装，不会后台刷写。",13,AgentUI.MUTED));
 }
 private static String signer(PackageInfo info)throws Exception{android.content.pm.Signature[] signatures=info.signingInfo==null?null:info.signingInfo.getApkContentsSigners();MaterialWire.require(signatures!=null&&signatures.length==1,"UPDATE_SIGNER_MISMATCH");return hex(MessageDigest.getInstance("SHA-256").digest(signatures[0].toByteArray()));}
 private static String hex(byte[] value){StringBuilder text=new StringBuilder();for(byte b:value)text.append(String.format(Locale.ROOT,"%02x",b&255));return text.toString();}
 private static String label(Exception error){String code=error.getMessage();if("UPDATE_CANCELLED".equals(code))return "下载已取消。";if(code!=null&&(code.contains("MISMATCH")||code.contains("INVALID")||code.contains("INCOMPATIBLE")))return "版本或安装包校验未通过，未开始安装。请重新检查更新。";return "更新检查或下载暂未完成，请检查网络及可用空间后重试。";}
}
